def search_substr(fullText, searchText, allowOverlap=True):
    if not searchText:
        return 0
    count = 0
    start = 0
    while start <= len(fullText) - len(searchText):
        pos = fullText.find(searchText, start)
        if pos != -1:
            count += 1
            start = pos + (1 if not allowOverlap else len(searchText))
        else:
            break
    return count
